geometry.source:
// =============================================================================================================================================
// geometry -- a molecule's ground-state shape: Hartree-Fock at the current geometry, the force on every nucleus from it, the nuclei moved
// downhill, again and again until the forces are gone (Levine ch. 15: the equilibrium geometry is where dE/dR = 0 for every nucleus).
//
// Each geometry step:
//   1. the SCF -- as hartree-fock.cl (its kernels, its loop), from the last step's density
//   2. the gradient, analytic -- the energy's derivative along each nucleus' x y z (Pulay's forces):
//        dE/dX = sum_ij P_ij dH_ij/dX  +  1/2 sum_ijkl Gamma_ijkl d(ij|kl)/dX  -  sum_ij W_ij dS_ij/dX  +  dV_nn/dX
//      P the total density, Gamma_ijkl = P_ij P_kl - P^a_ik P^a_jl - P^b_ik P^b_jl (coulomb less exchange), W = sum_occupied eps c c^T
//      (the energy-weighted density: the basis functions ride on the nuclei, so moving one changes the overlap -- the W term pays for
//      keeping the orbitals orthonormal). A Gaussian's derivative along its centre is two Gaussians: d/dA_x phi_i = 2a phi_(i+1) -
//      i phi_(i-1) -- every derivative integral is an ordinary one with one power raised or lowered. A centre-free operator (the overlap,
//      the kinetic energy, 1/r12) moves with its functions: the derivatives over all its centres sum to zero, so the last one is minus the
//      rest. The nuclear attraction's own nucleus is the third centre of <i|1/r_C|j>.
//   3. the step -- BFGS: the inverse Hessian (curvature) guessed as 1 / stiffness, then learned from how the gradient changed with each
//      step; the step -H^-1 g, at most max_step bohr along any coordinate
// until the largest force is under largest_force (hartree/bohr). The orbitals file at the end holds the final geometry; the inspector's
// energies and forces buffers hold each step's.
// =============================================================================================================================================

// the molecule and the run -- edit these (the geometry is only the start: any reasonable guess)
// @const molecule start = O 0 0 0; H 0 0.8 -0.5; H 0 -0.8 -0.5
// @const string basis = 6-31g*
// @const int charge = 0
// @const int mult = 0
// @const bool uhf = false
// @const int steps = 50
// @const double largest_force = 4.5e-4
// @const double max_step = 0.3
// @const double stiffness = 0.5
// @const int passes = 256
// @const double energy_change = 1e-10
// @const double largest_error = 1e-8
// @const string output = geometry
//
// largest_force: the usual threshold (Gaussian's default) -- bond lengths good to about 1e-3 angstrom; the SCF is held tighter than a
// single point's, the forces need it

// @use gaussian
// @buffer S n n
// @buffer H n n
// @buffer ERI quartets
// @buffer X m n
// @buffer P n n 2
// @buffer F n n 2
// @buffer C m n 2
// @buffer E m 2
// @buffer W n n
// @buffer Wd n n
// @buffer vnn 1
// @buffer G1 3*atoms n*n
// @buffer G2 12 quartets
// @buffer gradient 3 atoms
// @buffer hessian 3*atoms 3*atoms
// @buffer previous_x 3 atoms
// @buffer previous_g 3 atoms
// @buffer hy 3*atoms
// @buffer energies steps
// @buffer forces steps
// @kernel OneElectron n n
// @kernel TwoElectron quartets
// @kernel Fock n n
// @kernel Energy n n
// @kernel Nuclear 1
// @kernel Weighted n n
// @kernel GradientOne n n
// @kernel GradientTwo quartets
// @kernel Gather 3 atoms
// @kernel Record 1
// @kernel Step 1
// @report energy iteration force converged nuclear
//
// @do molecule start basis charge mult uhf
// @do guess P
// @repeat steps
// @do run Nuclear
// @do set nuclear = at(vnn,0)
// @do run OneElectron
// @do run TwoElectron
// @do orthogonalize S X
// @do diis reset
// @do set last = 0
// @repeat passes
// @do run Fock
// @do run Energy
// @do set energy = sum(W) + nuclear
// @do set change = abs(energy - last)
// @do set last = energy
// @do diis F P S X
// @do eigen F X C E
// @do density C P alpha beta
// @until iteration > 1 && change < energy_change && error < largest_error
// @do require converged == 1 "the SCF didn't converge at this geometry -- raise passes, or start nearer a sensible shape"
// @do run Weighted
// @do run GradientOne
// @do run GradientTwo
// @do run Gather
// @do set force = maxabs(gradient)
// @do run Record
// @do run Step
// @until force < largest_force
// @do output orbitals C E output

// ---- one-electron integrals -- element (i, j) of S and H ---------------------------------------------------------------------------------
// Per primitive pair: the Gaussian product theorem puts the pair on one centre P = (a A + b B) / p, p = a + b. Along each axis the overlap
// is E^{ij}_0 sqrt(pi / p); the kinetic energy comes from the second derivative of the right-hand function (its power j raised and lowered
// by 2); the nuclear attraction from the Hermite expansion against the Coulomb integrals R_{tuv} of each nucleus.
void OneElectron(Ir77Stage s) {
    uint n = (uint)s.n;
    uint i = s.i / n, j = s.i % n;

    __global int* fi = s.basis_functions + i * IR77_FUNCTION;
    __global int* fj = s.basis_functions + j * IR77_FUNCTION;
    __global double* atom_i = s.basis_atoms + fi[5] * 4;
    __global double* atom_j = s.basis_atoms + fj[5] * 4;
    double A[3] = {atom_i[0], atom_i[1], atom_i[2]};
    double B[3] = {atom_j[0], atom_j[1], atom_j[2]};

    double e[IR77_E_I * IR77_E_I * IR77_E_T];
    double scratch[IR77_R_SIZE];
    double r[IR77_R_SIZE];
    double sum_s = 0.0, sum_t = 0.0, sum_v = 0.0;

    for (int pa = 0; pa < fi[4]; pa++)
        for (int pb = 0; pb < fj[4]; pb++) {
            double a = s.basis_primitives[(fi[3] + pa) * 2], ca = s.basis_primitives[(fi[3] + pa) * 2 + 1];
            double b = s.basis_primitives[(fj[3] + pb) * 2], cb = s.basis_primitives[(fj[3] + pb) * 2 + 1];
            double p = a + b;
            double c = ca * cb;
            double P[3] = {(a * A[0] + b * B[0]) / p, (a * A[1] + b * B[1]) / p, (a * A[2] + b * B[2]) / p};
            double root = sqrt(IR77_PI / p);

            double ex[3][IR77_E_T];
            double s1[3], t1[3];
            for (int axis = 0; axis < 3; axis++) {
                int ia = fi[axis], jb = fj[axis];
                Ir77Hermite(ia, jb + 2, a, b, A[axis] - B[axis], e);

                s1[axis] = e[(ia * IR77_E_I + jb) * IR77_E_T] * root;
                double kinetic = -2.0 * b * b * e[(ia * IR77_E_I + jb + 2) * IR77_E_T] * root + b * (2.0 * jb + 1.0) * e[(ia * IR77_E_I + jb) * IR77_E_T] * root;
                if (jb >= 2) kinetic -= 0.5 * jb * (jb - 1) * e[(ia * IR77_E_I + jb - 2) * IR77_E_T] * root;
                t1[axis] = kinetic;

                for (int t = 0; t < IR77_E_T; t++) ex[axis][t] = e[(ia * IR77_E_I + jb) * IR77_E_T + t];
            }

            sum_s += c * s1[0] * s1[1] * s1[2];
            sum_t += c * (t1[0] * s1[1] * s1[2] + s1[0] * t1[1] * s1[2] + s1[0] * s1[1] * t1[2]);

            int tx = fi[0] + fj[0], ty = fi[1] + fj[1], tz = fi[2] + fj[2];
            for (int atom = 0; atom < (int)s.atoms; atom++) {
                __global double* nucleus = s.basis_atoms + atom * 4;
                Ir77Coulomb(tx, ty, tz, p, P[0] - nucleus[0], P[1] - nucleus[1], P[2] - nucleus[2], scratch, r);

                double sum = 0.0;
                for (int x = 0; x <= tx; x++)
                    for (int y = 0; y <= ty; y++)
                        for (int z = 0; z <= tz; z++) sum += ex[0][x] * ex[1][y] * ex[2][z] * r[(x * (ty + 1) + y) * (tz + 1) + z];

                sum_v += -nucleus[3] * c * 2.0 * IR77_PI / p * sum;
            }
        }

    s.S[s.i] = sum_s;
    s.H[s.i] = sum_t + sum_v;
}

// ---- two-electron integrals -- one unique (ij|kl) a work item, in the order Ir77Quartet indexes -------------------------------------------
void TwoElectron(Ir77Stage s) {
    int i, j, k, l;
    Ir77QuartetFunctions((long)s.i, &i, &j, &k, &l);
    s.ERI[s.i] = Ir77EriFunctions(i, j, k, l, s.basis_functions, s.basis_primitives, s.basis_atoms);
}

// ---- the Fock matrices -- element (i, j) of each spin's ----------------------------------------------------------------------------------
void Fock(Ir77Stage s) {
    uint n = (uint)s.n;
    uint i = s.i / n, j = s.i % n;
    __global double* pa = s.P;
    __global double* pb = s.P + n * n;

    double coulomb = 0.0, exchange_a = 0.0, exchange_b = 0.0;
    for (uint k = 0; k < n; k++)
        for (uint l = 0; l < n; l++) {
            uint kl = k * n + l;
            coulomb += (pa[kl] + pb[kl]) * s.ERI[Ir77Quartet(i, j, k, l)];
            double ikjl = s.ERI[Ir77Quartet(i, k, j, l)];
            exchange_a += pa[kl] * ikjl;
            exchange_b += pb[kl] * ikjl;
        }

    s.F[s.i] = s.H[s.i] + coulomb - exchange_a;
    s.F[n * n + s.i] = s.H[s.i] + coulomb - exchange_b;
}

// ---- the electronic energy's terms -- summed by the script ------------------------------------------------------------------------------
void Energy(Ir77Stage s) {
    uint nn = (uint)(s.n * s.n);
    double pa = s.P[s.i], pb = s.P[nn + s.i];
    s.W[s.i] = 0.5 * (pa * (s.H[s.i] + s.F[s.i]) + pb * (s.H[s.i] + s.F[nn + s.i]));
}

// ---- the nuclei's repulsion -- V_nn = sum_A<B Z_A Z_B / R_AB at the current geometry --------------------------------------------------------
void Nuclear(Ir77Stage s) {
    double v = 0.0;
    for (int a = 0; a < s.atoms; a++)
        for (int b = 0; b < a; b++) {
            __global double* A = s.basis_atoms + a * 4;
            __global double* B = s.basis_atoms + b * 4;
            double3 d = (double3)(A[0] - B[0], A[1] - B[1], A[2] - B[2]);
            v += A[3] * B[3] / length(d);
        }
    s.vnn[0] = v;
}

// ---- the energy-weighted density -- W_ij = sum over each spin's occupied orbitals eps_k c_ik c_jk ---------------------------------------------
void Weighted(Ir77Stage s) {
    uint n = (uint)s.n, m = (uint)s.m;
    uint i = s.i / n, j = s.i % n;
    double w = 0.0;
    for (int spin = 0; spin < 2; spin++) {
        int occupied = spin == 0 ? s.alpha : s.beta;
        __global double* c = s.C + spin * n * m;
        __global double* e = s.E + spin * m;
        for (int k = 0; k < occupied; k++) w += e[k] * c[i * m + k] * c[j * m + k];
    }
    s.Wd[s.i] = w;
}

// ---- derivative helpers -----------------------------------------------------------------------------------------------------------------

// one Hermite coefficient table's entry E^{ij}_t (0 when i or j is negative)
double HermiteAt(double* e, int i, int j, int t) { return i < 0 || j < 0 ? 0.0 : e[(i * IR77_E_I + j) * IR77_E_T + t]; }

// sum_tuv x_t y_u z_v R_tuv -- one charge distribution against a point (the nuclear attraction)
double Contract3(double* x, int lx, double* y, int ly, double* z, int lz, double* r, int sy, int sz) {
    double sum = 0.0;
    for (int t = 0; t <= lx; t++)
        for (int u = 0; u <= ly; u++)
            for (int v = 0; v <= lz; v++) sum += x[t] * y[u] * z[v] * r[(t * sy + u) * sz + v];
    return sum;
}

// sum_tuv sum_tau nu phi x_t y_u z_v (-1)^(tau+nu+phi) X_tau Y_nu Z_phi R_(t+tau)(u+nu)(v+phi) -- two charge distributions (an ERI)
double Contract6(double* x, int lx, double* y, int ly, double* z, int lz, double* X, int mx, double* Y, int my, double* Z, int mz, double* r, int sy, int sz) {
    double sum = 0.0;
    for (int t = 0; t <= lx; t++)
        for (int u = 0; u <= ly; u++)
            for (int v = 0; v <= lz; v++) {
                double left = x[t] * y[u] * z[v];
                if (left == 0.0) continue;
                for (int tau = 0; tau <= mx; tau++)
                    for (int nu = 0; nu <= my; nu++)
                        for (int phi = 0; phi <= mz; phi++) {
                            double sign = ((tau + nu + phi) & 1) ? -1.0 : 1.0;
                            sum += left * sign * X[tau] * Y[nu] * Z[phi] * r[((t + tau) * sy + (u + nu)) * sz + (v + phi)];
                        }
            }
    return sum;
}

// a derivative's Hermite vector along one axis -- d/dA: 2a E^{i+1,j} - i E^{i-1,j}; d/dB: 2b E^{i,j+1} - j E^{i,j-1}; or E^{ij} itself
void HermiteVector(double* e, int i, int j, int which, double a, double b, double* out) {
    for (int t = 0; t < IR77_E_T; t++) {
        if (which == 0) out[t] = HermiteAt(e, i, j, t);
        else if (which == 1) out[t] = 2.0 * a * HermiteAt(e, i + 1, j, t) - i * HermiteAt(e, i - 1, j, t);
        else out[t] = 2.0 * b * HermiteAt(e, i, j + 1, t) - j * HermiteAt(e, i, j - 1, t);
    }
}

// ---- the one-electron part of the gradient -- one function pair (i, j): P_ij dH_ij - W_ij dS_ij along every nucleus' x y z ----------------
// into G1's row for the pair (3 atoms long). Overlap and kinetic energy: d/dB = -d/dA. The nuclear attraction to C: d/dA, d/dB from the
// functions, d/dC = -(d/dA + d/dB).
void GradientOne(Ir77Stage s) {
    uint n = (uint)s.n;
    uint i = s.i / n, j = s.i % n;
    int D = 3 * s.atoms;
    __global double* out = s.G1 + (ulong)s.i * D;
    for (int e = 0; e < D; e++) out[e] = 0.0;

    double p = s.P[s.i] + s.P[n * n + s.i];
    double w = s.Wd[s.i];
    if (p == 0.0 && w == 0.0) return;

    __global int* fi = s.basis_functions + i * IR77_FUNCTION;
    __global int* fj = s.basis_functions + j * IR77_FUNCTION;
    int atom_a = fi[5], atom_b = fj[5];
    __global double* Ap = s.basis_atoms + atom_a * 4;
    __global double* Bp = s.basis_atoms + atom_b * 4;
    double A[3] = {Ap[0], Ap[1], Ap[2]};
    double B[3] = {Bp[0], Bp[1], Bp[2]};

    double e[3][IR77_E_I * IR77_E_I * IR77_E_T];
    double scratch[IR77_R_SIZE];
    double r[IR77_R_SIZE];

    for (int pa = 0; pa < fi[4]; pa++)
        for (int pb = 0; pb < fj[4]; pb++) {
            double a = s.basis_primitives[(fi[3] + pa) * 2], ca = s.basis_primitives[(fi[3] + pa) * 2 + 1];
            double b = s.basis_primitives[(fj[3] + pb) * 2], cb = s.basis_primitives[(fj[3] + pb) * 2 + 1];
            double q = a + b, c = ca * cb, root = sqrt(IR77_PI / q);
            double P[3] = {(a * A[0] + b * B[0]) / q, (a * A[1] + b * B[1]) / q, (a * A[2] + b * B[2]) / q};

            // per axis: S, T, and their d/dA -- the 1-D overlap S(i,j) = E^{ij}_0 sqrt(pi/p), the kinetic one from S(i, j +- 2)
            double s1[3], t1[3], ds[3], dt[3];
            for (int x = 0; x < 3; x++) {
                int ia = fi[x], jb = fj[x];
                Ir77Hermite(ia + 1, jb + 2, a, b, A[x] - B[x], e[x]);
                double S0[2], T0[2];  // [0] at i, [1] at i+1 / i-1 combined below
                for (int k = 0; k < 3; k++) {
                    int ii = ia + (k == 1 ? 1 : k == 2 ? -1 : 0);
                    double sv = HermiteAt(e[x], ii, jb, 0) * root;
                    double tv = -2.0 * b * b * HermiteAt(e[x], ii, jb + 2, 0) * root + b * (2.0 * jb + 1.0) * sv;
                    if (jb >= 2) tv -= 0.5 * jb * (jb - 1) * HermiteAt(e[x], ii, jb - 2, 0) * root;
                    if (ii < 0) sv = tv = 0.0;
                    if (k == 0) {
                        s1[x] = sv;
                        t1[x] = tv;
                    } else if (k == 1) {
                        S0[0] = sv;
                        T0[0] = tv;
                    } else {
                        S0[1] = sv;
                        T0[1] = tv;
                    }
                }
                ds[x] = 2.0 * a * S0[0] - ia * S0[1];
                dt[x] = 2.0 * a * T0[0] - ia * T0[1];
            }

            for (int x = 0; x < 3; x++) {
                int y = (x + 1) % 3, z = (x + 2) % 3;
                double d_overlap = ds[x] * s1[y] * s1[z];
                double d_kinetic = dt[x] * s1[y] * s1[z] + ds[x] * (t1[y] * s1[z] + s1[y] * t1[z]);
                double g = c * (p * d_kinetic - w * d_overlap);
                out[atom_a * 3 + x] += g;
                out[atom_b * 3 + x] -= g;
            }

            // the nuclear attraction -- each nucleus, the pair's Hermite expansion with one power raised on one axis at a time
            int tx = fi[0] + fj[0] + 1, ty = fi[1] + fj[1] + 1, tz = fi[2] + fj[2] + 1;
            for (int nucleus = 0; nucleus < s.atoms; nucleus++) {
                __global double* Cp = s.basis_atoms + nucleus * 4;
                Ir77Coulomb(tx, ty, tz, q, P[0] - Cp[0], P[1] - Cp[1], P[2] - Cp[2], scratch, r);
                double scale = -Cp[3] * c * 2.0 * IR77_PI / q * p;

                for (int x = 0; x < 3; x++) {
                    double vec[3][IR77_E_T], da[IR77_E_T], db[IR77_E_T];
                    for (int k = 0; k < 3; k++) HermiteVector(e[k], fi[k], fj[k], 0, a, b, vec[k]);
                    HermiteVector(e[x], fi[x], fj[x], 1, a, b, da);
                    HermiteVector(e[x], fi[x], fj[x], 2, a, b, db);

                    double* vx = x == 0 ? da : vec[0];
                    double* vy = x == 1 ? da : vec[1];
                    double* vz = x == 2 ? da : vec[2];
                    double dA = Contract3(vx, tx, vy, ty, vz, tz, r, ty + 1, tz + 1);
                    vx = x == 0 ? db : vec[0];
                    vy = x == 1 ? db : vec[1];
                    vz = x == 2 ? db : vec[2];
                    double dB = Contract3(vx, tx, vy, ty, vz, tz, r, ty + 1, tz + 1);

                    out[atom_a * 3 + x] += scale * dA;
                    out[atom_b * 3 + x] += scale * dB;
                    out[nucleus * 3 + x] -= scale * (dA + dB);
                }
            }
        }
}

// ---- the two-electron part -- one unique quartet: 1/2 Gamma d(ij|kl) along A B C (D = -(A + B + C)), 12 numbers into G2 ---------------------
// Gamma summed over the quartet's distinct permutations: (8 P_ij P_kl - 4 sum_spin (P_ik P_jl + P_il P_jk)) / its symmetry count
void GradientTwo(Ir77Stage s) {
    int i, j, k, l;
    Ir77QuartetFunctions((long)s.i, &i, &j, &k, &l);
    __global double* out = s.G2 + (ulong)s.i * 12;
    for (int e = 0; e < 12; e++) out[e] = 0.0;

    uint n = (uint)s.n;
    __global double* pa = s.P;
    __global double* pb = s.P + n * n;
    double total_ij = pa[i * n + j] + pb[i * n + j], total_kl = pa[k * n + l] + pb[k * n + l];
    double gamma = 8.0 * total_ij * total_kl - 4.0 * (pa[i * n + k] * pa[j * n + l] + pa[i * n + l] * pa[j * n + k] + pb[i * n + k] * pb[j * n + l] +
                                                      pb[i * n + l] * pb[j * n + k]);
    double symmetry = (i == j ? 2.0 : 1.0) * (k == l ? 2.0 : 1.0) * (i == k && j == l ? 2.0 : 1.0);
    gamma /= symmetry;
    if (fabs(gamma) < 1e-14) return;

    __global int* f[4] = {s.basis_functions + i * IR77_FUNCTION, s.basis_functions + j * IR77_FUNCTION, s.basis_functions + k * IR77_FUNCTION,
                          s.basis_functions + l * IR77_FUNCTION};
    double centre[4][3];
    for (int c = 0; c < 4; c++)
        for (int x = 0; x < 3; x++) centre[c][x] = s.basis_atoms[f[c][5] * 4 + x];

    double eab[3][IR77_E_I * IR77_E_I * IR77_E_T], ecd[3][IR77_E_I * IR77_E_I * IR77_E_T];
    double scratch[IR77_R_SIZE];
    double r[IR77_R_SIZE];
    double d[3][3] = {{0, 0, 0}, {0, 0, 0}, {0, 0, 0}};  // d/dA, d/dB, d/dC along x y z

    for (int p0 = 0; p0 < f[0][4]; p0++)
        for (int p1 = 0; p1 < f[1][4]; p1++) {
            double a = s.basis_primitives[(f[0][3] + p0) * 2], ca = s.basis_primitives[(f[0][3] + p0) * 2 + 1];
            double b = s.basis_primitives[(f[1][3] + p1) * 2], cb = s.basis_primitives[(f[1][3] + p1) * 2 + 1];
            double p = a + b;
            double P[3];
            for (int x = 0; x < 3; x++) {
                P[x] = (a * centre[0][x] + b * centre[1][x]) / p;
                Ir77Hermite(f[0][x] + 1, f[1][x] + 1, a, b, centre[0][x] - centre[1][x], eab[x]);
            }

            for (int p2 = 0; p2 < f[2][4]; p2++)
                for (int p3 = 0; p3 < f[3][4]; p3++) {
                    double c = s.basis_primitives[(f[2][3] + p2) * 2], cc = s.basis_primitives[(f[2][3] + p2) * 2 + 1];
                    double dd = s.basis_primitives[(f[3][3] + p3) * 2], cd = s.basis_primitives[(f[3][3] + p3) * 2 + 1];
                    double q = c + dd;
                    double Q[3];
                    for (int x = 0; x < 3; x++) {
                        Q[x] = (c * centre[2][x] + dd * centre[3][x]) / q;
                        Ir77Hermite(f[2][x] + 1, f[3][x], c, dd, centre[2][x] - centre[3][x], ecd[x]);
                    }
                    double alpha = p * q / (p + q);
                    double scale = ca * cb * cc * cd * 2.0 * pow(IR77_PI, 2.5) / (p * q * sqrt(p + q));

                    // the plain vectors
                    double ab[3][IR77_E_T], cdv[3][IR77_E_T];
                    for (int x = 0; x < 3; x++) {
                        HermiteVector(eab[x], f[0][x], f[1][x], 0, a, b, ab[x]);
                        HermiteVector(ecd[x], f[2][x], f[3][x], 0, c, dd, cdv[x]);
                    }

                    for (int x = 0; x < 3; x++) {
                        // R with one more order along x -- the raised function's
                        int lt[3] = {f[0][0] + f[1][0], f[0][1] + f[1][1], f[0][2] + f[1][2]};
                        int mt[3] = {f[2][0] + f[3][0], f[2][1] + f[3][1], f[2][2] + f[3][2]};
                        int sx = lt[0] + mt[0] + (x == 0), sy = lt[1] + mt[1] + (x == 1), sz = lt[2] + mt[2] + (x == 2);
                        Ir77Coulomb(sx, sy, sz, alpha, P[0] - Q[0], P[1] - Q[1], P[2] - Q[2], scratch, r);

                        double raised[IR77_E_T];
                        for (int which = 0; which < 3; which++) {
                            double* v[6] = {ab[0], ab[1], ab[2], cdv[0], cdv[1], cdv[2]};
                            int len[6] = {lt[0], lt[1], lt[2], mt[0], mt[1], mt[2]};
                            if (which == 0) HermiteVector(eab[x], f[0][x], f[1][x], 1, a, b, raised);
                            else if (which == 1) HermiteVector(eab[x], f[0][x], f[1][x], 2, a, b, raised);
                            else HermiteVector(ecd[x], f[2][x], f[3][x], 1, c, dd, raised);
                            int slot = which < 2 ? x : 3 + x;
                            v[slot] = raised;
                            len[slot] += 1;
                            d[which][x] += scale * Contract6(v[0], len[0], v[1], len[1], v[2], len[2], v[3], len[3], v[4], len[4], v[5], len[5], r, sy + 1, sz + 1);
                        }
                    }
                }
        }

    for (int x = 0; x < 3; x++) {
        out[x] = 0.5 * gamma * d[0][x];
        out[3 + x] = 0.5 * gamma * d[1][x];
        out[6 + x] = 0.5 * gamma * d[2][x];
        out[9 + x] = -0.5 * gamma * (d[0][x] + d[1][x] + d[2][x]);
    }
}

// ---- the gradient -- one nucleus' x, y or z: the one-electron rows, the quartets that touch it, the nuclei's repulsion ----------------------
void Gather(Ir77Stage s) {
    int D = 3 * s.atoms;
    int atom = s.i / 3, x = s.i % 3;
    uint n = (uint)s.n;

    double g = 0.0;
    for (uint pair = 0; pair < n * n; pair++) g += s.G1[(ulong)pair * D + s.i];

    for (long q = 0; q < s.quartets; q++) {
        int f[4];
        Ir77QuartetFunctions(q, &f[0], &f[1], &f[2], &f[3]);
        for (int c = 0; c < 4; c++)
            if (s.basis_functions[f[c] * IR77_FUNCTION + 5] == atom) g += s.G2[q * 12 + c * 3 + x];
    }

    __global double* A = s.basis_atoms + atom * 4;
    for (int b = 0; b < s.atoms; b++) {
        if (b == atom) continue;
        __global double* B = s.basis_atoms + b * 4;
        double3 d = (double3)(A[0] - B[0], A[1] - B[1], A[2] - B[2]);
        double r = length(d);
        g -= A[3] * B[3] * (x == 0 ? d.x : x == 1 ? d.y : d.z) / (r * r * r);
    }
    s.gradient[s.i] = g;
}

// ---- each step's energy and largest force -- the inspector plots them -------------------------------------------------------------------
void Record(Ir77Stage s) {
    int step = s.iteration - 1;
    if (step < 0 || step >= s.steps) return;
    s.energies[step] = s.energy;
    s.forces[step] = s.force;
}

// ---- the step -- BFGS on the inverse Hessian H (3 atoms square): H learned from s = x - x_prev, y = g - g_prev as
//   H += (s.y + y.H y) s s^T / (s.y)^2 - (H y s^T + s y^T H) / s.y      (skipped when s.y <= 0 -- the curvature's sign would flip)
// then x -= H g, every coordinate's move capped at max_step. Converged: the nuclei stay.
void Step(Ir77Stage s) {
    if (s.force < s.largest_force) return;
    int D = 3 * s.atoms;
    __global double* H = s.hessian;

    if (s.iteration == 1) {
        for (int a = 0; a < D; a++)
            for (int b = 0; b < D; b++) H[a * D + b] = a == b ? 1.0 / s.stiffness : 0.0;
    } else {
        // s and y in the previous buffers' place, then the update
        double sy = 0.0, yhy = 0.0;
        for (int a = 0; a < D; a++) {
            double sa = s.basis_atoms[(a / 3) * 4 + a % 3] - s.previous_x[a];
            double ya = s.gradient[a] - s.previous_g[a];
            s.previous_x[a] = sa;
            s.previous_g[a] = ya;
            sy += sa * ya;
        }
        if (sy > 1e-12) {
            for (int a = 0; a < D; a++) {
                double hy = 0.0;
                for (int b = 0; b < D; b++) hy += H[a * D + b] * s.previous_g[b];
                s.hy[a] = hy;
                yhy += s.previous_g[a] * hy;
            }
            for (int a = 0; a < D; a++)
                for (int b = 0; b < D; b++) {
                    double sa = s.previous_x[a], sb = s.previous_x[b];
                    H[a * D + b] += (sy + yhy) * sa * sb / (sy * sy) - (s.hy[a] * sb + sa * s.hy[b]) / sy;
                }
        }
    }

    // the move -- every coordinate's within max_step (the whole step scaled down together, its direction kept)
    double largest = 0.0;
    for (int a = 0; a < D; a++) {
        double move = 0.0;
        for (int b = 0; b < D; b++) move -= H[a * D + b] * s.gradient[b];
        s.previous_x[a] = move;  // the move for now -- the position is saved below
        largest = fmax(largest, fabs(move));
    }
    double scale = largest > s.max_step ? s.max_step / largest : 1.0;
    for (int a = 0; a < D; a++) {
        __global double* coordinate = s.basis_atoms + (a / 3) * 4 + a % 3;
        double move = scale * s.previous_x[a];
        s.previous_x[a] = *coordinate;
        s.previous_g[a] = s.gradient[a];
        *coordinate += move;
    }
}

hartree-fock.source:
// =============================================================================================================================================
// hartree-fock -- the self-consistent field for a molecule over a Gaussian basis set (Roothaan-Hall, Levine ch. 13-15). Restricted for a closed
// shell, unrestricted (alpha and beta apart) for an open one or when uhf is true -- the same equations either way: two spin densities, two
// Fock matrices; a closed shell's are equal. Writes the orbitals file (data/<output>.json) -- Fields' orbitals and levels programs draw it.
//
// The method, in the order the script below runs it:
//   1. the basis -- each atom's contracted Cartesian Gaussians (sto-3g, 6-31g, 6-31g*) (the molecule step)
//   2. the one-electron integrals -- overlap S_ij = <i|j>, and the core Hamiltonian H_ij = <i| -1/2 nabla^2 - sum_A Z_A / r_A |j> (OneElectron)
//   3. the two-electron integrals -- (ij|kl) = integral of i(1) j(1) (1/r12) k(2) l(2), each unique one once (TwoElectron) -- the costly part,
//      n^4 / 8 of them. Both by McMurchie-Davidson: products of Gaussians as Hermite Gaussians, the Coulomb part by the Boys function
//   4. an orthonormal basis -- X with X^T S X = 1 (canonical orthogonalization: S's eigenvectors over the roots of their eigenvalues)
//   5. a first density -- each atom's own (the superposition of atomic densities), half to each spin
//   6. the loop:
//        F_a = H + J(P_a + P_b) - K(P_a),  F_b likewise -- J_ij = sum_kl P_kl (ij|kl) (Coulomb), K_ij = sum_kl P_kl (ik|jl) (exchange) (Fock)
//        E = 1/2 sum_ij [ (P_a + P_b) H + P_a F_a + P_b F_b ]_ij + the nuclei's repulsion (Energy)
//        DIIS -- F replaced by the mix of the last few whose error F P S - S P F is least (that error is zero at self-consistency)
//        F C = S C eps -- solved as (X^T F X) C' = C' eps, C = X C'
//        P_a = the first alpha columns of C_a, outer products; P_b the first beta of C_b
//      until the energy stops changing and the error is small
//   7. the orbitals file
// =============================================================================================================================================

// the run's settings -- edit these
// @const molecule water = O 0 0 0.1173; H 0 0.7572 -0.4692; H 0 -0.7572 -0.4692
// @const string basis = 6-31g*
// @const int charge = 0
// @const int mult = 0
// @const bool uhf = false
// @const int passes = 256
// @const double energy_change = 1e-9
// @const double largest_error = 1e-7
// @const string output = orbitals
//
// mult (2S + 1) 0: the lowest the electron count allows (1 even, 2 odd); above 1 the run is unrestricted whatever uhf says

// @use gaussian
// @buffer S n n
// @buffer H n n
// @buffer ERI quartets
// @buffer X m n
// @buffer P n n 2
// @buffer F n n 2
// @buffer C m n 2
// @buffer E m 2
// @buffer W n n
// @kernel OneElectron n n
// @kernel TwoElectron quartets
// @kernel Fock n n
// @kernel Energy n n
// @report energy iteration error converged nuclear n
//
// @do molecule water basis charge mult uhf
// @do run OneElectron
// @do run TwoElectron
// @do orthogonalize S X
// @do guess P
// @do set last = 0
// @repeat passes
// @do run Fock
// @do run Energy
// @do set energy = sum(W) + nuclear
// @do set change = abs(energy - last)
// @do set last = energy
// @do diis F P S X
// @do eigen F X C E
// @do density C P alpha beta
// @until iteration > 1 && change < energy_change && error < largest_error
// @do output orbitals C E output

// ---- one-electron integrals -- element (i, j) of S and H ---------------------------------------------------------------------------------
// Per primitive pair: the Gaussian product theorem puts the pair on one centre P = (a A + b B) / p, p = a + b. Along each axis the overlap
// is E^{ij}_0 sqrt(pi / p); the kinetic energy comes from the second derivative of the right-hand function (its power j raised and lowered
// by 2); the nuclear attraction from the Hermite expansion against the Coulomb integrals R_{tuv} of each nucleus.
void OneElectron(Ir77Stage s) {
    uint n = (uint)s.n;
    uint i = s.i / n, j = s.i % n;

    __global int* fi = s.basis_functions + i * IR77_FUNCTION;
    __global int* fj = s.basis_functions + j * IR77_FUNCTION;
    __global double* atom_i = s.basis_atoms + fi[5] * 4;
    __global double* atom_j = s.basis_atoms + fj[5] * 4;
    double A[3] = {atom_i[0], atom_i[1], atom_i[2]};
    double B[3] = {atom_j[0], atom_j[1], atom_j[2]};

    double e[IR77_E_I * IR77_E_I * IR77_E_T];
    double scratch[IR77_R_SIZE];
    double r[IR77_R_SIZE];
    double sum_s = 0.0, sum_t = 0.0, sum_v = 0.0;

    for (int pa = 0; pa < fi[4]; pa++)
        for (int pb = 0; pb < fj[4]; pb++) {
            double a = s.basis_primitives[(fi[3] + pa) * 2], ca = s.basis_primitives[(fi[3] + pa) * 2 + 1];
            double b = s.basis_primitives[(fj[3] + pb) * 2], cb = s.basis_primitives[(fj[3] + pb) * 2 + 1];
            double p = a + b;
            double c = ca * cb;
            double P[3] = {(a * A[0] + b * B[0]) / p, (a * A[1] + b * B[1]) / p, (a * A[2] + b * B[2]) / p};
            double root = sqrt(IR77_PI / p);

            double ex[3][IR77_E_T];
            double s1[3], t1[3];
            for (int axis = 0; axis < 3; axis++) {
                int ia = fi[axis], jb = fj[axis];
                Ir77Hermite(ia, jb + 2, a, b, A[axis] - B[axis], e);

                s1[axis] = e[(ia * IR77_E_I + jb) * IR77_E_T] * root;
                double kinetic = -2.0 * b * b * e[(ia * IR77_E_I + jb + 2) * IR77_E_T] * root + b * (2.0 * jb + 1.0) * e[(ia * IR77_E_I + jb) * IR77_E_T] * root;
                if (jb >= 2) kinetic -= 0.5 * jb * (jb - 1) * e[(ia * IR77_E_I + jb - 2) * IR77_E_T] * root;
                t1[axis] = kinetic;

                for (int t = 0; t < IR77_E_T; t++) ex[axis][t] = e[(ia * IR77_E_I + jb) * IR77_E_T + t];
            }

            sum_s += c * s1[0] * s1[1] * s1[2];
            sum_t += c * (t1[0] * s1[1] * s1[2] + s1[0] * t1[1] * s1[2] + s1[0] * s1[1] * t1[2]);

            int tx = fi[0] + fj[0], ty = fi[1] + fj[1], tz = fi[2] + fj[2];
            for (int atom = 0; atom < (int)s.atoms; atom++) {
                __global double* nucleus = s.basis_atoms + atom * 4;
                Ir77Coulomb(tx, ty, tz, p, P[0] - nucleus[0], P[1] - nucleus[1], P[2] - nucleus[2], scratch, r);

                double sum = 0.0;
                for (int x = 0; x <= tx; x++)
                    for (int y = 0; y <= ty; y++)
                        for (int z = 0; z <= tz; z++) sum += ex[0][x] * ex[1][y] * ex[2][z] * r[(x * (ty + 1) + y) * (tz + 1) + z];

                sum_v += -nucleus[3] * c * 2.0 * IR77_PI / p * sum;
            }
        }

    s.S[s.i] = sum_s;
    s.H[s.i] = sum_t + sum_v;
}

// ---- two-electron integrals -- one unique (ij|kl) a work item, in the order Ir77Quartet indexes -------------------------------------------
void TwoElectron(Ir77Stage s) {
    int i, j, k, l;
    Ir77QuartetFunctions((long)s.i, &i, &j, &k, &l);
    s.ERI[s.i] = Ir77EriFunctions(i, j, k, l, s.basis_functions, s.basis_primitives, s.basis_atoms);
}

// ---- the Fock matrices -- element (i, j) of each spin's ----------------------------------------------------------------------------------
void Fock(Ir77Stage s) {
    uint n = (uint)s.n;
    uint i = s.i / n, j = s.i % n;
    __global double* pa = s.P;
    __global double* pb = s.P + n * n;

    double coulomb = 0.0, exchange_a = 0.0, exchange_b = 0.0;
    for (uint k = 0; k < n; k++)
        for (uint l = 0; l < n; l++) {
            uint kl = k * n + l;
            coulomb += (pa[kl] + pb[kl]) * s.ERI[Ir77Quartet(i, j, k, l)];
            double ikjl = s.ERI[Ir77Quartet(i, k, j, l)];
            exchange_a += pa[kl] * ikjl;
            exchange_b += pb[kl] * ikjl;
        }

    s.F[s.i] = s.H[s.i] + coulomb - exchange_a;
    s.F[n * n + s.i] = s.H[s.i] + coulomb - exchange_b;
}

// ---- the electronic energy's terms -- summed by the script ------------------------------------------------------------------------------
void Energy(Ir77Stage s) {
    uint nn = (uint)(s.n * s.n);
    double pa = s.P[s.i], pb = s.P[nn + s.i];
    s.W[s.i] = 0.5 * (pa * (s.H[s.i] + s.F[s.i]) + pb * (s.H[s.i] + s.F[nn + s.i]));
}

hydrogen.source:
// =============================================================================================================================================
// hydrogen -- the exact hydrogen-like orbital psi_nlm = R_nl(r) Y_lm(theta, phi) on a grid. R_nl is the associated Laguerre form (Levine
// ch. 6); Y_lm the real spherical harmonics (Levine ch. 5) -- m counts them in the order p x y z, d xy xz yz x2-y2 z2, f z3 xz2 yz2 z(x2-y2)
// xyz x(x2-3y2) y(3x2-y2). The energy is -Z^2 / (2 n^2). The report's norm -- psi^2 summed over the grid -- should come out 1: a check on the
// formula and on the grid (too coarse, or a box too small for the orbital, and it won't).
// Writes data/<output>.json, a grid: channel 0 psi, 1 the probability density -- Fields' grid program draws it.
// =============================================================================================================================================

// the run's settings -- edit these
// @const int n = 3
// @const int l = 2
// @const int m = 4
// @const double Z = 1
// @const int points = 96
// @const double extent = 30
// @const string output = hydrogen
//
// l under n (and at most 3), m from 0 to 2 l; the box is [-extent, extent]^3 bohr, points a side

// @const double cell = 2 * extent / (points - 1)
// @buffer psi points points points
// @buffer density points points points
// @kernel Orbital points points points
// @report energy norm
//
// @do run Orbital
// @do set norm = sum(density) * cell * cell * cell
// @do set energy = -Z * Z / (2 * n * n)
// @do output grid output -extent extent psi density

double Factorial(int k) {
    double f = 1.0;
    for (int i = 2; i <= k; i++) f *= (double)i;
    return f;
}

// the generalized Laguerre polynomial L_k^a(x), by its recurrence
double Laguerre(int k, double a, double x) {
    if (k == 0) return 1.0;
    double l0 = 1.0;
    double l1 = 1.0 + a - x;
    for (int i = 1; i < k; i++) {
        double l2 = ((2.0 * i + 1.0 + a - x) * l1 - (i + a) * l0) / (i + 1.0);
        l0 = l1;
        l1 = l2;
    }
    return l1;
}

// the real spherical harmonics times r^l -- solid harmonics, normalized on the sphere
double Solid(int l, int m, double3 p) {
    double const PI = 3.14159265358979323846;
    double x = p.x, y = p.y, z = p.z;
    if (l == 0) return 0.5 / sqrt(PI);
    if (l == 1) return sqrt(3.0 / (4.0 * PI)) * (m == 0 ? x : m == 1 ? y : z);
    if (l == 2) {
        double c = sqrt(15.0 / (4.0 * PI));
        if (m == 0) return c * x * y;
        if (m == 1) return c * x * z;
        if (m == 2) return c * y * z;
        if (m == 3) return 0.5 * c * (x * x - y * y);
        return sqrt(5.0 / (16.0 * PI)) * (2.0 * z * z - x * x - y * y);
    }
    if (m == 0) return sqrt(7.0 / (16.0 * PI)) * z * (2.0 * z * z - 3.0 * x * x - 3.0 * y * y);
    if (m == 1) return sqrt(21.0 / (32.0 * PI)) * x * (4.0 * z * z - x * x - y * y);
    if (m == 2) return sqrt(21.0 / (32.0 * PI)) * y * (4.0 * z * z - x * x - y * y);
    if (m == 3) return sqrt(105.0 / (16.0 * PI)) * z * (x * x - y * y);
    if (m == 4) return sqrt(105.0 / (4.0 * PI)) * x * y * z;
    if (m == 5) return sqrt(35.0 / (32.0 * PI)) * x * (x * x - 3.0 * y * y);
    return sqrt(35.0 / (32.0 * PI)) * y * (3.0 * x * x - y * y);
}

// one grid point -- x fastest
void Orbital(Ir77Stage s) {
    int x = s.i % s.points, y = (s.i / s.points) % s.points, z = s.i / (s.points * s.points);
    double3 p = (double3)(-s.extent + x * s.cell, -s.extent + y * s.cell, -s.extent + z * s.cell);

    int n = max(s.n, 1);
    int l = clamp(s.l, 0, min(n - 1, 3));
    int m = clamp(s.m, 0, 2 * l);
    double zeta = fmax(s.Z, 1.0);

    double r = length(p);
    double rho = 2.0 * zeta * r / n;

    // R_nl = sqrt((2Z/n)^3 (n-l-1)! / (2n (n+l)!)) e^(-rho/2) rho^l L_{n-l-1}^{2l+1}(rho) -- the r^l goes in with the solid harmonic
    double norm = sqrt(pow(2.0 * zeta / n, 3.0) * Factorial(n - l - 1) / (2.0 * n * Factorial(n + l)));
    double radial = norm * exp(-0.5 * rho) * pow(2.0 * zeta / n, (double)l) * Laguerre(n - l - 1, 2.0 * l + 1.0, rho);

    double psi = radial * Solid(l, m, p);
    s.psi[s.i] = psi;
    s.density[s.i] = psi * psi;
}

poisson.source:
// =============================================================================================================================================
// poisson -- the electrostatic potential of a charge distribution, by Jacobi relaxation: Laplacian(phi) = -4 pi rho (Gaussian units, atomic:
// charge in e, lengths in bohr, phi in hartree / e). Each sweep replaces phi with the average of its six neighbours plus the charge's share --
// the discrete equation solved for the centre point. Repeated, phi settles into the solution. Every `check` sweeps the error is measured:
// the largest |Laplacian(phi) + 4 pi rho| over the grid. phi = 0 on the box's faces (a grounded box).
//
// The charges: +q and -q (a dipole), Gaussian spheres of the given width, `separation` apart along x. Slow by design: Jacobi needs about as
// many sweeps as the grid has points along an edge, squared -- it shows the idea; real solvers use multigrid.
// Writes data/<output>.json, a grid: channel 0 the potential, 1 the charge density.
// =============================================================================================================================================

// the run's settings -- edit these
// @const double charge = 1
// @const double separation = 3
// @const double width = 0.6
// @const int points = 48
// @const double extent = 8
// @const int passes = 100
// @const int check = 50
// @const double tolerance = 1e-4
// @const string output = poisson

// @const double cell = 2 * extent / (points - 1)
// @buffer phi points points points
// @buffer next points points points
// @buffer rho points points points
// @buffer R points points points
// @kernel Start points points points
// @kernel Sweep points points points
// @kernel Residual points points points
// @report error iteration converged
//
// @do run Start
// @repeat passes
// @repeat check
// @do run Sweep
// @do swap phi next
// @until 0
// @do run Residual
// @do set error = maxabs(R)
// @until error < tolerance
// @do output grid output -extent extent phi rho

double Gaussian(double3 r, double w) { return exp(-dot(r, r) / (w * w)) / (pow(3.14159265358979323846, 1.5) * w * w * w); }

double At(Ir77Stage s, __global double* b, int x, int y, int z) {
    int const N = s.points;
    if (x < 0 || y < 0 || z < 0 || x >= N || y >= N || z >= N) return 0.0;
    return b[x + N * (y + N * z)];
}

double Around(Ir77Stage s, __global double* b, int x, int y, int z) {
    return At(s, b, x + 1, y, z) + At(s, b, x - 1, y, z) + At(s, b, x, y + 1, z) + At(s, b, x, y - 1, z) + At(s, b, x, y, z + 1) + At(s, b, x, y, z - 1);
}

void Start(Ir77Stage s) {
    int x = s.i % s.points, y = (s.i / s.points) % s.points, z = s.i / (s.points * s.points);
    double3 r = (double3)(-s.extent + x * s.cell, -s.extent + y * s.cell, -s.extent + z * s.cell);
    double3 apart = (double3)(0.5 * s.separation, 0.0, 0.0);
    s.rho[s.i] = s.charge * (Gaussian(r - apart, s.width) - Gaussian(r + apart, s.width));
    s.phi[s.i] = 0.0;
}

void Sweep(Ir77Stage s) {
    int x = s.i % s.points, y = (s.i / s.points) % s.points, z = s.i / (s.points * s.points);
    s.next[s.i] = (Around(s, s.phi, x, y, z) + s.cell * s.cell * 4.0 * 3.14159265358979323846 * s.rho[s.i]) / 6.0;
}

void Residual(Ir77Stage s) {
    int x = s.i % s.points, y = (s.i / s.points) % s.points, z = s.i / (s.points * s.points);
    double laplacian = (Around(s, s.phi, x, y, z) - 6.0 * s.phi[s.i]) / (s.cell * s.cell);
    s.R[s.i] = laplacian + 4.0 * 3.14159265358979323846 * s.rho[s.i];
}

schrodinger.source:
// =============================================================================================================================================
// schrodinger -- the lowest state of one particle in a potential, by evolution in imaginary time on the grid. Each step is
//   psi <- psi - dt H psi,   H = -1/2 Laplacian + V   (atomic units: hbar = m = 1, lengths in bohr, energies in hartree)
// Each state shrinks as exp(-E dt) a step, so the lowest one -- the ground state -- outlasts every other: psi settles into it, and
// <psi|H|psi> into its energy. Every `check` steps psi is normalized and measured: the energy, and the error |H psi - E psi| (largest over
// the grid) -- zero exactly when psi is an eigenstate.
//
// The grid limits it: the Laplacian is 7-point, so features smaller than a few cells (a bare Coulomb cusp) are smoothed -- the Coulomb
// potential is softened (-Z / sqrt(r^2 + a^2)) and the energy comes out a little above hydrogen's -Z^2/2. A finer grid or a smaller box
// brings it down. dt is held under the explicit scheme's limit, 0.9 / (the grid's largest kinetic energy + the potential's largest |V|).
// psi = 0 past the box's faces. Writes data/<output>.json, a grid: channel 0 psi, 1 the energy density psi H psi, 2 the potential.
// =============================================================================================================================================

// the run's settings -- edit these
// @const int potential = 1
// @const double strength = 1
// @const double softening = 0.2
// @const double step = 0.05
// @const int points = 64
// @const double extent = 8
// @const int passes = 400
// @const int check = 50
// @const double tolerance = 1e-4
// @const string output = schrodinger
//
// potential: 0 Coulomb (Z = strength, softened by `softening`), 1 harmonic (omega^2 = strength -- E = 1.5 omega), 2 a double well along x,
// 3 a box (side 8); step: imaginary time a step (the stability limit caps it); passes x check steps at most

// @const double cell = 2 * extent / (points - 1)
// @const double volume = cell * cell * cell
// @buffer psi points points points
// @buffer next points points points
// @buffer V points points points
// @buffer Hpsi points points points
// @buffer W points points points
// @buffer R points points points
// @kernel Start points points points
// @kernel Step points points points
// @kernel Normalize points points points
// @kernel Apply points points points
// @kernel Residual points points points
// @report energy error iteration converged dt
//
// @do run Start
// @do set dt = min(step, 0.9 / (6 / (cell * cell) + maxabs(V)))
// @repeat passes
// @repeat check
// @do run Step
// @do swap psi next
// @until 0
// @do set norm = sqrt(sumsq(psi) * volume)
// @do run Normalize
// @do run Apply
// @do set energy = sum(W) * volume
// @do run Residual
// @do set error = maxabs(R)
// @until iteration > 1 && error < tolerance
// @do output grid output -extent extent psi W V

double3 Point(Ir77Stage s, int x, int y, int z) { return (double3)(-s.extent + x * s.cell, -s.extent + y * s.cell, -s.extent + z * s.cell); }

double Potential(Ir77Stage s, double3 r) {
    double d = length(r);
    if (s.potential == 0) return -s.strength / sqrt(d * d + s.softening * s.softening);
    if (s.potential == 1) return 0.5 * s.strength * d * d;
    if (s.potential == 2) {
        double a = 3.0;
        double x2 = r.x * r.x - a * a;
        return 0.05 * s.strength * x2 * x2 / (a * a) + 0.05 * (r.y * r.y + r.z * r.z);
    }
    return fabs(r.x) < 4.0 && fabs(r.y) < 4.0 && fabs(r.z) < 4.0 ? 0.0 : 10.0 * s.strength;
}

// a buffer at a grid point -- 0 past the box
double At(Ir77Stage s, __global double* b, int x, int y, int z) {
    int const N = s.points;
    if (x < 0 || y < 0 || z < 0 || x >= N || y >= N || z >= N) return 0.0;
    return b[x + N * (y + N * z)];
}

// H psi at one point -- the 7-point Laplacian
double H(Ir77Stage s, __global double* psi, int x, int y, int z) {
    double centre = At(s, psi, x, y, z);
    double around = At(s, psi, x + 1, y, z) + At(s, psi, x - 1, y, z) + At(s, psi, x, y + 1, z) + At(s, psi, x, y - 1, z) + At(s, psi, x, y, z + 1) +
                    At(s, psi, x, y, z - 1);
    double laplacian = (around - 6.0 * centre) / (s.cell * s.cell);
    return -0.5 * laplacian + s.V[s.i] * centre;
}

// the start -- anything that overlaps the ground state; a soft exponential
void Start(Ir77Stage s) {
    int x = s.i % s.points, y = (s.i / s.points) % s.points, z = s.i / (s.points * s.points);
    double3 r = Point(s, x, y, z);
    s.V[s.i] = Potential(s, r);
    s.psi[s.i] = exp(-0.5 * length(r));
}

void Step(Ir77Stage s) {
    int x = s.i % s.points, y = (s.i / s.points) % s.points, z = s.i / (s.points * s.points);
    s.next[s.i] = s.psi[s.i] - s.dt * H(s, s.psi, x, y, z);
}

void Normalize(Ir77Stage s) { s.psi[s.i] /= s.norm; }

// H psi, and psi H psi -- it sums to <psi|H|psi>, the energy
void Apply(Ir77Stage s) {
    int x = s.i % s.points, y = (s.i / s.points) % s.points, z = s.i / (s.points * s.points);
    double h = H(s, s.psi, x, y, z);
    s.Hpsi[s.i] = h;
    s.W[s.i] = s.psi[s.i] * h;
}

void Residual(Ir77Stage s) { s.R[s.i] = s.Hpsi[s.i] - s.energy * s.psi[s.i]; }

slater-atom.source:
// =============================================================================================================================================
// slater-atom -- one atom, Hartree-Fock over Slater functions R(r) = N r^l exp(-zeta r) Y_lm (Levine ch. 11, 14). A Slater function has the
// nuclear cusp (the density's sharp peak, slope -2Z, at the nucleus) and the right exponential tail; a Gaussian has neither. One centre, so
// every integral is closed form: the angular parts by 3j symbols, the radial ones by factorials and whole-power incomplete gammas.
// Writes data/<output>.json, an orbitals file (function kind 1) -- Fields' orbitals and levels programs draw it.
//
//   basis    even-tempered per l (zeta_i = first ratio^i), s p d f -- dense and wide enough to land near the Hartree-Fock limit for H to Kr
//   spin     alpha and beta apart (Hund's rule: an open subshell's alpha set fills first), each spherically averaged -- its electrons spread
//            evenly over the subshell's m. Closed-shell atoms are exact restricted Hartree-Fock; a half-filled or one-electron subshell (H, N,
//            P ...) is its true ground state; other open shells are the spherically averaged atom
//   filling  ground: Madelung order -- 1s 2s 2p 3s 3p 4s 3d 4p (Cr and Cu as 4s2 3d4 / 4s2 3d9, not their real 4s1); or the arrays
//            s_shells p_shells d_shells f_shells -- any subshells to n = 5 (H's 2p: s 0, p 1; an excited Be: s 2 1, p 1)
//   average  an open subshell's same-spin electrons interact as the average over its determinants: q(q-1) pairs, not q^2 -- no electron
//            meets itself (H 2p1 lands on -1/8 exactly)
//   empty    a neutral atom's empty Hartree-Fock orbitals are unbound (they feel N electrons: no net charge), so they're replaced by improved
//            virtual orbitals -- the same orbitals in the field of N - 1 (one electron out of the highest subshell), kept orthogonal to the
//            occupied ones. They're bound: the atom's excited orbitals, a Rydberg series (H: exactly hydrogen's 2s 2p 3d 4f)
//
// The loop, per spin and l (a block of the l's functions -- every m of it shares one radial operator):
//   F_l = h_l + sum_l2 (2 l2 + 1) [ J(P_l2 alpha + P_l2 beta) - sum_k (l k l2; 0 0 0)^2 K^k(P_l2 this spin) ]  -  the open subshell's own
//   share, (1 - scale) G(Q_l) -- J_ab = sum_xy P_xy R^0(ab|xy), K^k_ab = sum_xy P_xy R^k(ax|by); P per m component: the radial orbitals'
//   electrons / (2l + 1), c c^T; Q the open subshell's part of it
// =============================================================================================================================================

// the atom -- edit these
// @const int Z = 35
// @const int charge = 0
// @const bool ground = true
// @const double[] s_shells = 2 2 1
// @const double[] p_shells = 1
// @const double[] d_shells =
// @const double[] f_shells =
// @const string output = atom
//
// ground true: the Madelung ground state (Z - charge electrons); false: the arrays -- each subshell's electrons, lowest n first: s_shells
// for 1s 2s 3s 4s 5s, p_shells 2p 3p 4p 5p, d_shells 3d 4d 5d, f_shells 4f 5f (H's 2p: s_shells = 0, p_shells = 1)

// the run -- the SCF's limits, and the empty orbitals kept (per l, below `bound` hartree)
// @const int passes = 128
// @const double energy_change = 1e-9
// @const double largest_error = 1e-7
// @const int virtuals = 2
// @const double bound = -1e-3

// the basis -- k functions per l, zeta from `first` up by its ratio (the small end reaches a Rydberg orbital: 4f is exp(-r/4))
// @const int k0 = 22
// @const int k1 = 18
// @const int k2 = 14
// @const int k3 = 10
// @const double first = 0.1
// @const double ratio0 = 1.45
// @const double ratio1 = 1.5
// @const double ratio2 = 1.6
// @const double ratio3 = 1.65
// @const int radial = 5
// @const int b0 = k0 * k0
// @const int b1 = k1 * k1
// @const int b2 = k2 * k2
// @const int b3 = k3 * k3
// @const int tables = (b0 + b1 + b2 + b3) * (b0 + b1 + b2 + b3) + b0 * (b0 + b1 + b2 + b3) + b1 * (b0 + 2 * b1 + 2 * b2 + 2 * b3) + b2 * (b0 + 2 * b1 + 3 * b2 + 3 * b3) + b3 * (b0 + 2 * b1 + 3 * b2 + 4 * b3)
//
// tables: every R^k the operators use, worked out once -- per (l1, l2) the coulomb R^0(ab|cd) (k1^2 k2^2), then the exchange R^k(ac|bd)
// for each k from |l1 - l2| to l1 + l2 by 2 (k1^2 k2^2 each)
// @buffer R tables
// @buffer q radial 4 2
// @buffer check 2
// @buffer opened 4 2
// @buffer scale 4 2
// @buffer filled 4 2
// @buffer keep 4
// @buffer hole 3
// @buffer Dh k0 k0
// @buffer zeta0 k0
// @buffer zeta1 k1
// @buffer zeta2 k2
// @buffer zeta3 k3
// @buffer S0 k0 k0
// @buffer S1 k1 k1
// @buffer S2 k2 k2
// @buffer S3 k3 k3
// @buffer H0 k0 k0
// @buffer H1 k1 k1
// @buffer H2 k2 k2
// @buffer H3 k3 k3
// @buffer X0 m0 k0
// @buffer X1 m1 k1
// @buffer X2 m2 k2
// @buffer X3 m3 k3
// @buffer F0 k0 k0 2
// @buffer F1 k1 k1 2
// @buffer F2 k2 k2 2
// @buffer F3 k3 k3 2
// @buffer C0 m0 k0 2
// @buffer C1 m1 k1 2
// @buffer C2 m2 k2 2
// @buffer C3 m3 k3 2
// @buffer E0 m0 2
// @buffer E1 m1 2
// @buffer E2 m2 2
// @buffer E3 m3 2
// @buffer P0 k0 k0 2
// @buffer P1 k1 k1 2
// @buffer P2 k2 k2 2
// @buffer P3 k3 k3 2
// @buffer Q0 k0 k0 2
// @buffer Q1 k1 k1 2
// @buffer Q2 k2 k2 2
// @buffer Q3 k3 k3 2
// @buffer G0 k0 k0 2
// @buffer G1 k1 k1 2
// @buffer G2 k2 k2 2
// @buffer G3 k3 k3 2
// @buffer W0 k0 k0 2
// @buffer W1 k1 k1 2
// @buffer W2 k2 k2 2
// @buffer W3 k3 k3 2
// @kernel Occupy 1
// @kernel OneElectron k0 k0 4
// @kernel Integrals tables
// @kernel Core k0 k0 8
// @kernel Density k0 k0 8
// @kernel Fock k0 k0 8
// @kernel Energy k0 k0 8
// @kernel Hole 1
// @kernel HoleDensity k0 k0
// @kernel Virtual k0 k0 8
// @kernel Keep 1
// @report energy iteration error converged
//
// @do require Z >= 1 && Z <= 36 "Z from 1 (H) to 36 (Kr)"
// @do run Occupy
// @do require at(check,1) == 1 "a subshell over 2(2l+1) electrons, more subshells than 1s-5s 2p-5p 3d-5d 4f-5f, or (ground) more electrons than 4p holds"
// @do require at(check,0) == Z - charge "the subshells hold a different count from the atom's electrons (Z - charge)"
// @do run OneElectron
// @do run Integrals
// @do orthogonalize S0 X0 m0 1e-9
// @do orthogonalize S1 X1 m1 1e-9
// @do orthogonalize S2 X2 m2 1e-9
// @do orthogonalize S3 X3 m3 1e-9
// @do run Core
// @do eigen F0 X0 C0 E0
// @do eigen F1 X1 C1 E1
// @do eigen F2 X2 C2 E2
// @do eigen F3 X3 C3 E3
// @do run Density
// @do set last = 0
// @repeat passes
// @do run Fock
// @do run Energy
// @do set energy = sum(W0) + sum(W1) + sum(W2) + sum(W3)
// @do set change = abs(energy - last)
// @do set last = energy
// @do diis F0 P0 S0 X0 F1 P1 S1 X1 F2 P2 S2 X2 F3 P3 S3 X3
// @do eigen F0 X0 C0 E0
// @do eigen F1 X1 C1 E1
// @do eigen F2 X2 C2 E2
// @do eigen F3 X3 C3 E3
// @do run Density
// @until iteration > 1 && change < energy_change && error < largest_error
//
// the improved virtual orbitals -- the operator in the field of N - 1, each block's empty space diagonalized again
// @do run Hole
// @do run HoleDensity
// @do run Virtual
// @do subspace F0 C0 E0 at(filled,0) at(filled,4)
// @do subspace F1 C1 E1 at(filled,1) at(filled,5)
// @do subspace F2 C2 E2 at(filled,2) at(filled,6)
// @do subspace F3 C3 E3 at(filled,3) at(filled,7)
// @do run Keep
// @do output atom output Z charge q keep zeta0 C0 E0 zeta1 C1 E1 zeta2 C2 E2 zeta3 C3 E3

// ---- a block's buffers and sizes -- l 0 .. 3 -------------------------------------------------------------------------------------------
#define BLOCK(s, name, l) ((l) == 0 ? (s).name##0 : (l) == 1 ? (s).name##1 : (l) == 2 ? (s).name##2 : (s).name##3)

int Functions(Ir77Stage s, int l) { return l == 0 ? s.k0 : l == 1 ? s.k1 : l == 2 ? s.k2 : s.k3; }

int Rank(Ir77Stage s, int l) { return l == 0 ? s.m0 : l == 1 ? s.m1 : l == 2 ? s.m2 : s.m3; }

double Zeta(Ir77Stage s, int l, int i) {
    double ratio = l == 0 ? s.ratio0 : l == 1 ? s.ratio1 : l == 2 ? s.ratio2 : s.ratio3;
    return s.first * pown(ratio, i);
}

double Factorial(int n) {
    double f = 1.0;
    for (int i = 2; i <= n; i++) f *= (double)i;
    return f;
}

// the radial normalization -- N = sqrt((2 zeta)^(2l+3) / (2l+2)!)
double Norm(int l, double zeta) { return sqrt(pown(2.0 * zeta, 2 * l + 3) / Factorial(2 * l + 2)); }

// a radial orbital's electrons -- q[r + radial (l + 4 spin)]
double Electrons(Ir77Stage s, int r, int l, int spin) { return r < s.radial ? s.q[r + s.radial * (l + 4 * spin)] : 0.0; }

// ---- the integrals ------------------------------------------------------------------------------------------------------------------------

// int_0^inf r^q exp(-c r) dr = q! / c^(q+1)
double Gamma(int q, double c) { return Factorial(q) / pown(c, q + 1); }

// R^k between two pairs of Slater functions -- r^m1 exp(-a r) on electron 1, r^m2 exp(-b r) on electron 2 (each m carrying the volume's r^2):
// int int f1 f2 r<^k / r>^(k+1). Split at r2 = r1: inside, int_0^r1 t^n e^-bt = n!/b^(n+1) [1 - e^-b r1 sum_j<=n (b r1)^j / j!]; outside,
// int_r1^inf t^p e^-bt = p!/b^(p+1) e^-b r1 sum_j<=p (b r1)^j / j!. The inside's bracket integrates to the tail of a series whose whole sum
// is known -- summed as that tail, nothing cancels; the more compact pair goes on electron 1, so the tail falls off at least as 1/2^j.
double Radial(int m1, double a, int m2, double b, int k) {
    if (b > a) {
        int mt = m1;
        m1 = m2;
        m2 = mt;
        double t = a;
        a = b;
        b = t;
    }
    double g = a + b;
    int n = m2 + k, p = m2 - k - 1, q = m1 - k - 1;

    // inside: sum_j>n (q+j)! b^j / (j! g^(q+j+1)) x n! / b^(n+1) -- its first term (q+n+1)! / ((n+1) g^(q+n+2)), then by ratio
    double term = Factorial(q + n + 1) / ((n + 1) * pown(g, q + n + 2));
    double inside = term;
    for (int j = n + 1; j < n + 400; j++) {
        term *= b * (q + j + 1) / ((j + 1) * g);
        inside += term;
        if (term < 1e-17 * inside) break;
    }

    // outside: p!/b^(p+1) sum_j<=p b^j / j! (m1+k+j)! / g^(m1+k+j+1)
    term = Factorial(p) / pown(b, p + 1) * Factorial(m1 + k) / pown(g, m1 + k + 1);
    double outside = term;
    for (int j = 0; j < p; j++) {
        term *= b / (j + 1) * (m1 + k + j + 1) / g;
        outside += term;
    }
    return inside + outside;
}

// (l1 k l2; 0 0 0)^2 -- zero unless l1 + k + l2 is even and they make a triangle
double ThreeJ2(int l1, int k, int l2) {
    int t = l1 + k + l2;
    if (t % 2 != 0 || k < abs(l1 - l2) || k > l1 + l2) return 0.0;
    int h = t / 2;
    double value = Factorial(t - 2 * l1) * Factorial(t - 2 * k) * Factorial(t - 2 * l2) / Factorial(t + 1);
    double ratio = Factorial(h) / (Factorial(h - l1) * Factorial(h - k) * Factorial(h - l2));
    return value * ratio * ratio;
}

// where a table starts in R -- (l1, l2) in order, each the coulomb R^0 then its exchange R^k (k from |l1 - l2| by 2); which: 0 the coulomb,
// 1 + j the j-th exchange
long Table(Ir77Stage s, int l1, int l2, int which) {
    long at = 0;
    for (int x = 0; x < 4; x++)
        for (int y = 0; y < 4; y++) {
            long size = (long)Functions(s, x) * Functions(s, x) * Functions(s, y) * Functions(s, y);
            int tables = 2 + min(x, y);
            if (x == l1 && y == l2) return at + which * size;
            at += tables * size;
        }
    return at;
}

// one block's two-electron operator on element (a, b) of block l1 from densities of block l2 (k2 x k2): (2 l2 + 1) [ J(j1 + j2) - sum_k
// (l1 k l2; 0 0 0)^2 K^k(x) ] -- J_ab = sum_cd D_cd R^0(ab|cd), K^k_ab = sum_cd D_cd R^k(ac|bd). Any of the three may be 0: none.
double Operator(Ir77Stage s, int l1, int a, int b, int l2, __global double* j1, __global double* j2, __global double* x) {
    int k1 = Functions(s, l1), k2 = Functions(s, l2);
    __global double* coulomb_table = s.R + Table(s, l1, l2, 0) + (long)(a * k1 + b) * k2 * k2;
    double coulomb = 0.0, exchange = 0.0;
    if (j1 || j2)
        for (int cd = 0; cd < k2 * k2; cd++) coulomb += ((j1 ? j1[cd] : 0.0) + (j2 ? j2[cd] : 0.0)) * coulomb_table[cd];
    if (x)
        for (int j = 0, k = abs(l1 - l2); k <= l1 + l2; j++, k += 2) {
            double w = ThreeJ2(l1, k, l2);
            __global double* table = s.R + Table(s, l1, l2, 1 + j);
            double sum = 0.0;
            for (int c = 0; c < k2; c++)
                for (int d = 0; d < k2; d++) sum += x[c * k2 + d] * table[((long)(a * k2 + c) * k1 + b) * k2 + d];
            exchange += w * sum;
        }
    return (2.0 * l2 + 1.0) * (coulomb - exchange);
}

// every block with electrons on element (a, b) of block l1, this spin -- coulomb with both spins, exchange with this one
double TwoElectron(Ir77Stage s, int spin, int l1, int a, int b) {
    double f = 0.0;
    for (int l2 = 0; l2 < 4; l2++) {
        double any = 0.0;
        for (int r = 0; r < s.radial; r++) any += Electrons(s, r, l2, 0) + Electrons(s, r, l2, 1);
        if (any <= 0.0) continue;

        int k2 = Functions(s, l2);
        __global double* p = BLOCK(s, P, l2);
        f += Operator(s, l1, a, b, l2, p, p + k2 * k2, p + spin * k2 * k2);
    }
    return f;
}

// ---- the kernels --------------------------------------------------------------------------------------------------------------------------

// the occupations -- Madelung or the arrays, split by Hund's rule; each spin's open subshell per l and its self-interaction's share; check
// [0] the electrons placed, [1] 1 when every subshell fits
void Occupy(Ir77Stage s) {
    double shells[4][5];
    for (int l = 0; l < 4; l++)
        for (int r = 0; r < 5; r++) shells[l][r] = 0.0;
    int fits = 1;

    if (s.ground) {
        int order[8][2] = {{1, 0}, {2, 0}, {2, 1}, {3, 0}, {3, 1}, {4, 0}, {3, 2}, {4, 1}};
        double left = (double)(s.Z - s.charge);
        for (int o = 0; o < 8 && left > 0.0; o++) {
            int n = order[o][0], l = order[o][1];
            double room = 2.0 * (2 * l + 1);
            shells[l][n - l - 1] = fmin(left, room);
            left -= shells[l][n - l - 1];
        }
        if (left > 0.0) fits = 0;
    } else {
        __global double* arrays[4] = {s.s_shells, s.p_shells, s.d_shells, s.f_shells};
        int counts[4] = {s.s_shells_count, s.p_shells_count, s.d_shells_count, s.f_shells_count};
        for (int l = 0; l < 4; l++) {
            if (counts[l] > 5 - l) fits = 0;
            for (int r = 0; r < counts[l] && r < 5 - l; r++) {
                shells[l][r] = arrays[l][r];
                if (arrays[l][r] < 0.0 || arrays[l][r] > 2.0 * (2 * l + 1)) fits = 0;
            }
        }
    }

    double placed = 0.0;
    for (int l = 0; l < 4; l++) {
        double room = 2.0 * l + 1.0;  // one spin's room in the subshell
        for (int spin = 0; spin < 2; spin++) {
            s.opened[l + 4 * spin] = -1.0;
            s.scale[l + 4 * spin] = 1.0;
            s.filled[l + 4 * spin] = 0.0;
        }
        for (int r = 0; r < s.radial; r++) {
            double total = r < 5 ? shells[l][r] : 0.0;
            double alpha = fmin(total, room), beta = total - alpha;
            placed += total;
            s.q[r + s.radial * l] = alpha;
            s.q[r + s.radial * (l + 4)] = beta;

            for (int spin = 0; spin < 2; spin++) {
                double e = spin == 0 ? alpha : beta;
                if (e > 0.0) s.filled[l + 4 * spin] = r + 1;
                // a partly filled subshell (l > 0): its q electrons meet each other q(q-1) times, not q^2 -- the highest one counts
                if (l > 0 && e > 0.0 && e < room) {
                    s.opened[l + 4 * spin] = r;
                    s.scale[l + 4 * spin] = e > 1.0 ? room * (e - 1.0) / (e * (room - 1.0)) : 0.0;
                }
            }
        }
    }
    s.check[0] = placed;
    s.check[1] = fits;
}

// one element of R -- which table it's in, then R^k over its four functions (normalized)
void Integrals(Ir77Stage s) {
    long e = s.i;
    for (int l1 = 0; l1 < 4; l1++)
        for (int l2 = 0; l2 < 4; l2++) {
            int k1 = Functions(s, l1), k2 = Functions(s, l2);
            long size = (long)k1 * k1 * k2 * k2;
            long start = Table(s, l1, l2, 0);
            int tables = 2 + min(l1, l2);
            if (e < start || e >= start + tables * size) continue;

            int which = (int)((e - start) / size);
            long at = (e - start) % size;
            if (which == 0) {
                // R^0(ab|cd) at ((a k1 + b) k2 + c) k2 + d -- a b on l1, c d on l2
                int d = at % k2, c = (at / k2) % k2, b = (at / (k2 * k2)) % k1, a = at / ((long)k2 * k2 * k1);
                double za = Zeta(s, l1, a), zb = Zeta(s, l1, b), zc = Zeta(s, l2, c), zd = Zeta(s, l2, d);
                double n4 = Norm(l1, za) * Norm(l1, zb) * Norm(l2, zc) * Norm(l2, zd);
                s.R[e] = n4 * Radial(2 * l1 + 2, za + zb, 2 * l2 + 2, zc + zd, 0);
            } else {
                // R^k(ac|bd) at ((a k2 + c) k1 + b) k2 + d -- a b on l1, c d on l2
                int k = abs(l1 - l2) + 2 * (which - 1);
                int d = at % k2, b = (at / k2) % k1, c = (at / ((long)k2 * k1)) % k2, a = at / ((long)k2 * k1 * k2);
                double za = Zeta(s, l1, a), zb = Zeta(s, l1, b), zc = Zeta(s, l2, c), zd = Zeta(s, l2, d);
                double n4 = Norm(l1, za) * Norm(l1, zb) * Norm(l2, zc) * Norm(l2, zd);
                s.R[e] = n4 * Radial(l1 + l2 + 2, za + zc, l1 + l2 + 2, zb + zd, k);
            }
            return;
        }
}

// S and h = T + V of one l -- every integral a q! / c^(q+1); the exponents too
void OneElectron(Ir77Stage s) {
    int K = s.k0;
    int i = s.i % K, j = (s.i / K) % K, l = s.i / (K * K);
    int k = Functions(s, l);
    if (i >= k || j >= k) return;

    double zi = Zeta(s, l, i), zj = Zeta(s, l, j), c = zi + zj, nn = Norm(l, zi) * Norm(l, zj);
    double L = (double)l;

    // 1/2 int [R_i' R_j' + l(l+1) R_i R_j / r^2] r^2 dr
    double kinetic = zi * zj * Gamma(2 * l + 2, c) - L * c * Gamma(2 * l + 1, c);
    if (l > 0) kinetic += (L * L + L * (L + 1.0)) * Gamma(2 * l, c);
    kinetic *= 0.5 * nn;
    double nuclear = -(double)s.Z * nn * Gamma(2 * l + 1, c);

    BLOCK(s, S, l)[i * k + j] = nn * Gamma(2 * l + 2, c);
    BLOCK(s, H, l)[i * k + j] = kinetic + nuclear;
    if (j == 0) BLOCK(s, zeta, l)[i] = zi;
}

// the start -- the bare nucleus' orbitals: F = h for both spins
void Core(Ir77Stage s) {
    int K = s.k0;
    int a = s.i % K, b = (s.i / K) % K, block = s.i / (K * K), l = block % 4, spin = block / 4;
    int k = Functions(s, l);
    if (a >= k || b >= k) return;
    BLOCK(s, F, l)[spin * k * k + a * k + b] = BLOCK(s, H, l)[a * k + b];
}

// P per m component: sum_i q_i / (2l+1) c_i c_i^T (this spin's radial orbitals); Q the open subshell's part
void Density(Ir77Stage s) {
    int K = s.k0;
    int a = s.i % K, b = (s.i / K) % K, block = s.i / (K * K), l = block % 4, spin = block / 4;
    int k = Functions(s, l), m = Rank(s, l);
    if (a >= k || b >= k) return;

    __global double* c = BLOCK(s, C, l) + spin * m * k;
    int open = (int)s.opened[l + 4 * spin];
    double p = 0.0, q = 0.0;
    for (int r = 0; r < s.radial && r < m; r++) {
        double w = Electrons(s, r, l, spin) / (2.0 * l + 1.0);
        if (w == 0.0) continue;
        double d = w * c[a * m + r] * c[b * m + r];
        p += d;
        if (r == open) q += d;
    }
    BLOCK(s, P, l)[spin * k * k + a * k + b] = p;
    BLOCK(s, Q, l)[spin * k * k + a * k + b] = q;
}

// F = h + the two-electron operator - the open subshell's own share: (1 - scale) G(Q), kept in G for the energy
void Fock(Ir77Stage s) {
    int K = s.k0;
    int a = s.i % K, b = (s.i / K) % K, block = s.i / (K * K), l = block % 4, spin = block / 4;
    int k = Functions(s, l);
    if (a >= k || b >= k) return;

    double f = BLOCK(s, H, l)[a * k + b] + TwoElectron(s, spin, l, a, b);

    double cut = 0.0;
    if (s.opened[l + 4 * spin] >= 0.0 && s.scale[l + 4 * spin] < 1.0) {
        __global double* q = BLOCK(s, Q, l) + spin * k * k;
        cut = (1.0 - s.scale[l + 4 * spin]) * Operator(s, l, a, b, l, q, 0, q);
    }
    BLOCK(s, F, l)[spin * k * k + a * k + b] = f - cut;
    BLOCK(s, G, l)[spin * k * k + a * k + b] = cut;
}

// the energy's terms -- E = 1/2 sum_spin sum_l (2l+1) tr[P (h + F)] with F before the self-interaction came out, less that share's own
// 1/2 (2l+1) tr[Q (1 - scale) G(Q)]
void Energy(Ir77Stage s) {
    int K = s.k0;
    int a = s.i % K, b = (s.i / K) % K, block = s.i / (K * K), l = block % 4, spin = block / 4;
    int k = Functions(s, l);
    if (a >= k || b >= k) return;
    int at = spin * k * k + a * k + b;
    double p = BLOCK(s, P, l)[at], q = BLOCK(s, Q, l)[at], g = BLOCK(s, G, l)[at];
    BLOCK(s, W, l)[at] = 0.5 * (2.0 * l + 1.0) * (p * (BLOCK(s, H, l)[a * k + b] + BLOCK(s, F, l)[at] + g) - q * g);
}

// the highest occupied radial orbital, either spin -- hole [spin, l, radial index]
void Hole(Ir77Stage s) {
    double highest = -1e300;
    for (int spin = 0; spin < 2; spin++)
        for (int l = 0; l < 4; l++) {
            int m = Rank(s, l);
            for (int r = 0; r < s.radial && r < m; r++)
                if (Electrons(s, r, l, spin) > 0.0 && BLOCK(s, E, l)[spin * m + r] > highest) {
                    highest = BLOCK(s, E, l)[spin * m + r];
                    s.hole[0] = spin;
                    s.hole[1] = l;
                    s.hole[2] = r;
                }
        }
}

// one electron of the hole subshell, spread over its m -- per m component, 1 / (2l+1) c c^T
void HoleDensity(Ir77Stage s) {
    int spin = (int)s.hole[0], l = (int)s.hole[1], r = (int)s.hole[2];
    int k = Functions(s, l), m = Rank(s, l);
    int x = s.i % s.k0, y = s.i / s.k0;
    if (x >= k || y >= k) return;
    __global double* c = BLOCK(s, C, l) + spin * m * k;
    s.Dh[x * k + y] = c[x * m + r] * c[y * m + r] / (2.0 * l + 1.0);
}

// the operator the empty orbitals feel: every electron in full, less the hole's -- its coulomb, and its exchange in its own spin
void Virtual(Ir77Stage s) {
    int K = s.k0;
    int a = s.i % K, b = (s.i / K) % K, block = s.i / (K * K), l = block % 4, spin = block / 4;
    int k = Functions(s, l);
    if (a >= k || b >= k) return;

    int hole_spin = (int)s.hole[0], hole_l = (int)s.hole[1];
    double f = BLOCK(s, H, l)[a * k + b] + TwoElectron(s, spin, l, a, b);
    f -= Operator(s, l, a, b, hole_l, s.Dh, 0, spin == hole_spin ? s.Dh : 0);
    BLOCK(s, F, l)[spin * k * k + a * k + b] = f;
}

// the radial orbitals written per l -- the occupied ones, then up to `virtuals` empty ones that are bound (in either spin)
void Keep(Ir77Stage s) {
    int open = 0;
    for (int l = 0; l < 4; l++)
        for (int r = 0; r < s.radial; r++) open = open || Electrons(s, r, l, 0) != Electrons(s, r, l, 1);

    for (int l = 0; l < 4; l++) {
        int m = Rank(s, l), keep = 0;
        for (int r = 0; r < s.radial; r++)
            if (Electrons(s, r, l, 0) + Electrons(s, r, l, 1) > 0.0) keep = r + 1;
        __global double* e = BLOCK(s, E, l);
        for (int r = keep, last = keep + s.virtuals; r < last && r < m; r++)
            if (e[r] < s.bound || (open && e[m + r] < s.bound)) keep = r + 1;
        s.keep[l] = keep;
    }
}
